/**
 * The bits of chrome the four story screens share: type, plates, a focus ring
 * and keyboard-only navigation (D37, AC-18.1).
 *
 * It lives inside this lane's folder rather than in `src/game/ui/` because the
 * brief's scope rule says a helper another lane might also create belongs to
 * whoever needs it, not in a shared file two agents race to write. Everything
 * it draws is dressed from `@game/ui/theme`, so when the lanes are reconciled
 * the tokens already match.
 *
 * Nothing here can render a failure: there is no error state, no red, and no
 * disabled-with-a-cross treatment. A locked item is drawn dim and still
 * focusable, because "you can look at Pluto before you can fly there" is the
 * map's whole emotional job (D31, AC-22b.1).
 */

export interface TextOptions {
  readonly size?: number;
  readonly color?: string;
  readonly align?: "left" | "center" | "right";
  readonly wrapWidth?: number;
  readonly lang?: Lang;
  readonly alpha?: number;
  readonly letterSpacing?: boolean;
}

/** A Phaser Text dressed from the theme. Never takes a literal font name. */
export function label(
  scene: Phaser.Scene,
  x: number,
  y: number,
  content: string,
  options: TextOptions = {},
): Phaser.GameObjects.Text {
  const size = options.size ?? TYPE.body;
  const lang = options.lang ?? "en";
  const style: Phaser.Types.GameObjects.Text.TextStyle = {
    fontFamily: FONT_STACK,
    fontSize: `${size}px`,
    color: options.color ?? INK.text,
    align: options.align ?? "left",
  };
  if (options.wrapWidth !== undefined) {
    style.wordWrap = { width: options.wrapWidth, useAdvancedWrap: true };
  }
  const text = scene.add.text(x, y, content, style);
  text.setLineSpacing(Math.round(size * (lineHeightEm(lang) - 1)));
  // D41 INCREASED LETTER SPACING, READ FROM THE SETTING (UR-38).
  //
  // This was `options.letterSpacing ?? false`, so the setting was off on every
  // story screen no matter what the child had chosen - eleven scenes, none of
  // which passed the flag, because nothing made them. It is a reading
  // intervention (Zorzi et al. 2012) and the story screens are where the prose
  // is. A caller may still force it either way; what it may no longer do is
  // silently default to off. See `lib/typography.ts`.
  text.setLetterSpacing(
    letterSpacingPx(size, options.letterSpacing ?? typographyOf(scene).increasedLetterSpacing),
  );
  if (options.alpha !== undefined) text.setAlpha(options.alpha);
  return text;
}

/** Chrome copy: a button or row label, lowercased per D41 unless told not to. */
/**
 * Chrome copy: a button or row label.
 *
 * `uppercase` is D41's letter-case setting and defaults to the SETTING rather
 * than to false (UR-38). Chrome only, never a pilot name or a ship name - that
 * is why this is a separate function from `label`.
 */
export function chrome(
  scene: Phaser.Scene,
  x: number,
  y: number,
  content: string,
  uppercase?: boolean,
  options: TextOptions = {},
): Phaser.GameObjects.Text {
  const upper = uppercase ?? typographyOf(scene).uppercase;
  return label(scene, x, y, chromeCase(content, upper), {
    size: TYPE.label,
    ...options,
  });
}

/**
 * A plate's props.
 *
 * THIS IS `ui/plate.PlateProps`, not a copy of four of its fields (UR-69). It
 * used to be four optional strings and a number, which is why a scene that
 * wanted a corner treatment or a rim had no way to ask for one and drew its own
 * rounded rect instead. `corner`, `rim` and `rhythm` arrive here for free
 * because the type is the component's, so adding a prop to the component adds
 * it to all eight callers of this function at once - which is the whole of what
 * UR-69 asked for.
 */
export type PlateOptions = PlateProps;

/**
 * A contrast plate. Word labels and prose both sit on one (rubric 8).
 *
 * THE DEFAULT IS OPAQUE, AND IT WAS 0.94.
 *
 * At card size, six per cent of sky is not a tint - it is a SHAPE. A blind
 * critic probed `results.png` and found the stage report's body reading L* 10.0
 * everywhere except inside the moon's footprint, where it read L* 11.9: a
 * circle visible inside a panel that is meant to be a surface. The same probe
 * on `warp.png` reads 9.9 against 12.1 in the sliver where the same moon passes
 * behind the sentence card, so it was never one screen's bug.
 *
 * It also made the CONTRAST EVIDENCE a fiction. `skyText` registers text drawn
 * on a scene's own panel with `plateAlpha: 1` and the panel's swatch as the
 * fill, so V-22.8 has been measuring these surfaces as opaque the whole time
 * while they were drawn at 0.94 over whatever sky happened to be behind them.
 * Filling them flat makes the drawing agree with the measurement.
 *
 * `SKY_PLATE` keeps its 0.97 and is untouched: a plate cut to one line of type
 * is a sheet of glass, and 3% of sky through a 40 px strip is a tint. Passing
 * `alpha` here is still allowed for that kind of plate, and
 * `tests/unit/scenes/plateOpacity.test.ts` holds every CARD-sized caller to 1.
 */
export function plate(
  scene: Phaser.Scene,
  x: number,
  y: number,
  w: number,
  h: number,
  options: PlateOptions = {},
): Phaser.GameObjects.Graphics {
  return drawPlate(scene, { x, y, w, h }, options);
}

// ---------------------------------------------------------------------------
// Sky-borne text (AC-22.8)
// ---------------------------------------------------------------------------

/**
 * EVERY PIECE OF TEXT DRAWN OVER THE WORLD GOES THROUGH HERE.
 *
 * The defect: the word plate had a contrast plate and measured 17.4:1, while the
 * headline that names the screen was drawn straight onto the sky. Mars' sky is a
 * warm ochre; coral ink on it is 1.6:1. "the map is drawn" was 1.19:1 in pink on
 * the ending's dawn, and it STRADDLED a silhouette edge, so half the word sat on
 * grey and half on sky - a child cannot read that at any size.
 *
 * So a headline is not a Text object any more, it is a Text object ON A PLATE,
 * and the plate is sized from the text's own measured bounds so it cannot be
 * mis-set by hand. Every one of them also REGISTERS ITS COLOUR PAIR on the
 * scene, which is what lets the rubric measure the whole inventory instead of
 * the one pair somebody remembered to check.
 *
 * `behind` defaults to worst-case white in the contrast module, so a scene never
 * has to know its own sky to be measured honestly.
 *
 * The registry itself lives in `skyTextRegistry.ts`, away from Phaser, because
 * the thing most likely to go wrong is the LIFETIME: a scene object survives
 * `scene.restart()`, so a registry that never cleared would have handed the
 * capture three copies of the Director map's rows and called it coverage.
 * Re-exported here so scenes keep importing one module.
 */
export { recordSkyText, skyTextSamples, clearSkyText } from "./skyTextRegistry";

export interface SkyTextOptions extends TextOptions {
  /** Stable id for the evidence row, e.g. "warp.heading". */
  readonly id: string;
  /** Screen id for the evidence row, e.g. "warp". */
  readonly screen: string;
  /** Text depth. The plate is drawn one below it. */
  readonly depth?: number;
  readonly originX?: number;
  readonly originY?: number;
  readonly padX?: number;
  readonly padY?: number;
  /**
   * Suppress the plate ONLY where the text already sits on a panel the scene
   * drew itself. `plateFill` then names that panel's colour, so the row is
   * still measured - "it's on a panel, trust me" is how 1.19:1 shipped.
   */
  readonly plated?: boolean;
  readonly plateFill?: string;
}

export interface PlatedText {
  readonly text: Phaser.GameObjects.Text;
  readonly plate: Phaser.GameObjects.Graphics | null;
  /**
   * Plate first, then text - THE ORDER MATTERS AND DEPTH DOES NOT SAVE YOU.
   *
   * A Phaser Container renders its children in LIST ORDER and ignores their
   * depth unless something calls `sort`. Warp and Beacon put their header in a
   * container, and the first version of this helper created the text and then
   * the plate, so the plate - correctly set to depth-1 - was added second and
   * painted a black rectangle straight over the headline it was there to make
   * legible. Adding this array is how a caller gets the order right without
   * having to know that.
   */
  readonly objects: readonly Phaser.GameObjects.GameObject[];
  /** Re-lays the plate around new content. */
  setText(content: string): void;
  destroy(): void;
}

/**
 * Text over the world, on a plate, measured.
 *
 * The plate is drawn from `text.getBounds()` AFTER the string is set, so it
 * follows the origin, the line count, the letter spacing and the Devanagari line
 * height without any of those being restated here. `setText` redraws it, which
 * is what stops a headline that changes ("PLACED", the per-stop board) from
 * keeping a plate cut for the string it used to hold.
 */
export function skyText(
  scene: Phaser.Scene,
  x: number,
  y: number,
  content: string,
  options: SkyTextOptions,
): PlatedText {
  const depth = options.depth ?? 10;
  const padX = options.padX ?? SKY_PLATE.padX;
  const padY = options.padY ?? SKY_PLATE.padY;
  // The graphics object is created FIRST so it lands earlier on the display
  // list (and earlier in any container it is added to) and therefore renders
  // UNDER the text. It is drawn into afterwards, once the text has bounds.
  const wantsPlate = options.plated !== true;
  const g = wantsPlate ? scene.add.graphics().setDepth(depth - 1) : null;

  const text = label(scene, x, y, content, options).setDepth(depth);
  text.setOrigin(options.originX ?? 0, options.originY ?? 0);

  const layout = (): void => {
    if (g === null) return;
    g.clear();
    if (text.text.length === 0) return;
    const b = text.getBounds();
    // THE SAME COMPONENT the cards are drawn with, on the `chip` rhythm
    // (UR-69). The padding is still a parameter here rather than read from
    // `PLATE_RHYTHM.chip` directly, because callers override `padY` - the
    // header lines pass 10 - and `PLATE_RHYTHM.chip` is pinned to `SKY_PLATE`'s
    // 22/12 so the two cannot drift.
    paintPlate(
      g,
      {
        x: b.x - padX,
        y: b.y - padY,
        w: b.width + padX * 2,
        h: b.height + padY * 2,
      },
      {
        fill: SKY_PLATE.fill,
        alpha: SKY_PLATE.alpha,
        stroke: SKY_PLATE.stroke,
        strokeAlpha: 0.55,
        radius: SKY_PLATE.radius,
        rhythm: "chip",
      },
    );
  };
  layout();

  record(scene, {
    screen: options.screen,
    id: options.id,
    color: options.color ?? INK.text,
    plateFill: wantsPlate ? SKY_PLATE.fill : (options.plateFill ?? INK.panel),
    plateAlpha: wantsPlate ? SKY_PLATE.alpha : 1,
  });

  return {
    text,
    plate: g,
    objects: g === null ? [text] : [g, text],
    setText(next: string) {
      text.setText(next);
      layout();
    },
    destroy() {
      g?.destroy();
      text.destroy();
    },
  };
}

export interface FocusTarget {
  readonly id: string;
  /** Screen-space bounds the ring is drawn around. */
  readonly x: number;
  readonly y: number;
  readonly w: number;
  readonly h: number;
  /** Fired on Enter or Space. */
  readonly activate?: () => void;
  /** Locked stops stay focusable; this only changes the ring's voice. */
  readonly locked?: boolean;
  /**
   * THE FORWARD ACTION. The one thing the player came to this screen to do:
   * continue, launch, light the beacon. It holds focus when the screen opens,
   * so the obvious next action is Enter and nothing else.
   *
   * Replay, retry and back are never primary. On the stage report that means
   * "continue" is focused and "fly it again" is one key away, not the other way
   * round - a child who presses Enter on reflex should move on with their run,
   * not silently repeat the stage they just finished.
   *
   * Declared per target rather than inferred from list order so that a screen
   * can lay its buttons out however it reads best (results puts replay on the
   * left, because that is where a "back" reads) without that choosing what
   * Enter does.
   */
  readonly primary?: boolean;
  /**
   * Opt OUT of the focus swell (UR-111). Default true; a control grows while it
   * is focused and holds it, like every other control in the game.
   *
   * The one caller that says false is the Director map's seven PLANETS. A stop
   * is not a plate with a label on it - it is a disc, a beacon, a glow and a
   * caption, drawn with the Lantern hovering over it, and UR-92 deliberately
   * took the ring off it because the ship already says which stop the screen is
   * about. Swelling a planet 1.5% would be a fourth "you are here" on a screen
   * that was cut down to one, and only the parts that are PLATES could be found
   * to swell anyway - the caption would grow and the world it names would not.
   * The two chips at the top right of the same screen are plates, and they do
   * grow.
   */
  readonly pop?: boolean;
}

export interface FocusRing {
  moveTo(target: FocusTarget): void;
  /**
   * Take the ring off the screen on a named beat.
   *
   * IT IS ON THE COMPONENT BECAUSE THE BREATH IS. `moveTo` starts a
   * `repeat: -1` tween on `alpha`, and a screen that fades the ring itself is
   * a second tween on that one property - which the pulse then wins. Measured
   * in the served build of the warp break, sampled every animation frame from
   * the last keystroke of the sentence:
   *
   *              panelRoot.alpha   ring.graphics.alpha
   *     Pluto       0.000               1.000   (+1413 ms)
   *     Mars        0.000               0.856   (+1187 ms)
   *     Neptune     0.000               0.865   (+1323 ms)
   *
   * The card was gone and the gold outline was still painted around where it
   * had been, at every stop. A caller cannot fix that from outside because the
   * pulse handle is this closure's.
   */
  fadeOut(durationMs: number, ease: string): void;
  readonly graphics: Phaser.GameObjects.Graphics;
  destroy(): void;
}

/**
 * The visible focus state AC-18.1 requires. One ring, moved between targets
 * with a Back.Out pop so the eye tracks it; it is never hidden.
 */
/**
 * `reducedMotion` IS OPTIONAL, AND OMITTING IT MEANS "NO BREATH" (UR-112).
 *
 * The ring breathes while it holds a control - a slight alpha pulse, the spec
 * in `ui/focusPop.focusPulse`, shared with `ui/chrome.FocusRing` so the five
 * menu screens and the seven story screens cannot answer "what does focused
 * look like" differently again (UR-111's whole subject).
 *
 * Nine scenes call this and only the ones that have their reduced-motion flag
 * to hand pass it. That is deliberate and it is the SAFE default: a screen that
 * has not been wired up yet gets the ring it has always had, and the way to get
 * the pulse is to hand over the flag that can switch it off. The alternative -
 * a `reducedMotion = false` default - is a screen that pulses at a child who
 * asked the game to stop moving, which is the failure this argument exists to
 * prevent (D41, AC-19.3).
 */
export function createFocusRing(
  scene: Phaser.Scene,
  depth = 40,
  reducedMotion?: boolean,
): FocusRing {
  const g = scene.add.graphics().setDepth(depth);
  let tween: Phaser.Tweens.Tween | null = null;
  let pulse: Phaser.Tweens.Tween | null = null;

  /** Breathe, once the arrival has landed. Never both at once on `alpha`. */
  const startPulse = (): void => {
    pulse?.remove();
    pulse = null;
    // Undefined means this screen has not opted in; true means calm motion.
    const spec = reducedMotion === undefined ? null : focusPulse(reducedMotion);
    if (spec === null) {
      g.setAlpha(1);
      return;
    }
    pulse = scene.tweens.add({
      targets: g,
      alpha: { from: spec.alpha.from, to: spec.alpha.to },
      duration: spec.duration,
      ease: spec.ease,
      yoyo: spec.yoyo,
      repeat: spec.repeat,
    });
  };

  const draw = (t: FocusTarget): void => {
    const o = SPACE.focusRingOffset;
    g.clear();
    // The ring is the plate's own geometry with one offset, so it is the
    // component's (UR-69, `ui/plate.paintFocusRing`). Two passes: the ring
    // itself, and a soft halo one step wider.
    paintFocusRing(g, t, INK.accent, { halo: INK.accentSoft });
  };

  return {
    graphics: g,
    moveTo(target: FocusTarget) {
      draw(target);
      tween?.remove();
      // The breath belongs to the control the ring is ON, so it stops when the
      // ring leaves and starts again when the arrival has landed.
      pulse?.remove();
      pulse = null;
      g.setScale(1);
      const arrive = focusArrive();
      tween = scene.tweens.add({
        targets: g,
        alpha: arrive.alpha,
        duration: arrive.duration,
        ease: arrive.ease,
        onComplete: () => {
          tween = null;
          startPulse();
        },
      });
    },
    fadeOut(durationMs: number, ease: string) {
      // BOTH TWEENS FIRST. The arrival can still be running and the breath
      // repeats forever; either one writes `alpha` after this fade has set it,
      // which is the defect the interface note above measures.
      tween?.remove();
      tween = null;
      pulse?.remove();
      pulse = null;
      scene.tweens.add({
        targets: g,
        alpha: 0,
        duration: durationMs,
        ease,
        onComplete: () => {
          g.setVisible(false);
        },
      });
    },
    destroy() {
      tween?.remove();
      pulse?.remove();
      g.destroy();
    },
  };
}

// ---------------------------------------------------------------------------
// The focus swell (UR-111)
// ---------------------------------------------------------------------------

/**
 * ============== GROWING A CONTROL THAT IS ONLY A RECTANGLE ==============
 *
 * `ui/controls.ts` grows a focused control by scaling a container it built
 * itself: the control IS an object, so there is something to scale. The seven
 * story screens on this kit are the other shape entirely - each one draws its
 * own plate and its own label straight onto the scene and then hands
 * `createKeyboardMenu` a bare `{x, y, w, h}` - so there was no node to scale
 * and those screens had no focus growth at all. Focus was carried by the ring's
 * alpha alone, and a child moving between the Title, the map and the briefing
 * met three different answers to "what does focused look like".
 *
 * ================== WHY THE KIT WRAPS, AND THE SCENES DO NOT ==================
 * The alternative was a `node` field on `FocusTarget` that every screen fills
 * in. That is seven scene edits for one behaviour, it is seven chances to
 * forget, and the two screens that most need it (Briefing, Results) are owned
 * by other lanes. So the kit does what `controls.ts` does - it wraps what it is
 * given in a container and scales THAT - and finds "what it is given" from the
 * rectangle, using `plateRectOf` (every plate remembers its box) and
 * `Text.getBounds()` (every label can be measured). A screen gets the behaviour
 * by passing a target, which it already does.
 *
 * ================== THE TWO-CONTAINER SPLIT IS STILL THE POINT ==================
 * The wrapper is a NEW container placed at the target's CENTRE, and the parts
 * are re-based into it. Nothing that already existed is scaled, moved or
 * re-depthed: the scene's own tweens keep running on the same objects, at the
 * same local coordinates, and the focus ring and the hit zone keep being struck
 * around the declared rectangle, which never breathes. Anchoring the container
 * on the centre rather than the top-left is what makes the growth a SWELL
 * rather than a drift to the right and down - the same property
 * `focusPopShift` buys for a kit control whose anchor is fixed by layout.
 */

/** A control's parts, lifted into one container so they can breathe together. */
interface Pop {
  readonly id: string;
  readonly container: Phaser.GameObjects.Container;
  readonly scale: number;
  popped: boolean;
  tween: Phaser.Tweens.Tween | null;
  setPopped(popped: boolean): void;
  unwrap(): void;
}

/** A part the kit can measure, with its box in the space it is drawn in. */
interface Part {
  readonly obj: Phaser.GameObjects.GameObject & {
    x: number;
    y: number;
    depth: number;
    parentContainer: Phaser.GameObjects.Container | null;
  };
  readonly parent: Phaser.GameObjects.Container | null;
  readonly box: PopBox;
  readonly order: number;
}

/**
 * The world box of one drawn object, or null when it is not a thing this kit
 * can measure.
 *
 * TEXT AND PLATES ONLY, DELIBERATELY. Those two are what a control on these
 * screens is made of, they are both drawn through this file, and both can say
 * where they are. A `Zone` is skipped because a hit area is not part of the
 * drawing; a bare `Graphics` with no plate on it is skipped because it cannot
 * be measured at all, which is the honest answer for the map's planet discs and
 * the reason those targets opt out of the swell rather than half-swelling.
 */
function partBox(obj: Phaser.GameObjects.GameObject): PopBox | null {
  if (obj instanceof Phaser.GameObjects.Zone) return null;
  if (obj instanceof Phaser.GameObjects.Text) {
    const b = obj.getBounds();
    return { x: b.x, y: b.y, w: b.width, h: b.height };
  }
  const local = plateRectOf(obj);
  if (local === null) return null;
  const withTransform = obj as unknown as {
    getWorldTransformMatrix?: () => Phaser.GameObjects.Components.TransformMatrix;
  };
  const m = withTransform.getWorldTransformMatrix?.();
  if (m === undefined) return { x: local.x, y: local.y, w: local.w, h: local.h };
  // Two corners, so a parent container that is offset or scaled is followed.
  // Nothing on these screens rotates, and an axis-aligned box is all the
  // containment test wants.
  const tl = m.transformPoint(local.x, local.y, new Phaser.Math.Vector2());
  const br = m.transformPoint(local.x + local.w, local.y + local.h, new Phaser.Math.Vector2());
  return { x: tl.x, y: tl.y, w: br.x - tl.x, h: br.y - tl.y };
}

/** Everything on the screen that is part of the control drawn at `box`. */
function partsAt(scene: Phaser.Scene, box: PopBox, claimed: Set<unknown>): Part[] {
  const found: Part[] = [];
  const walk = (
    objects: Phaser.GameObjects.GameObject[],
    parent: Phaser.GameObjects.Container | null,
  ): void => {
    objects.forEach((obj, i) => {
      if (obj instanceof Phaser.GameObjects.Container) {
        // A container is never itself a part: it is somebody's grouping, and
        // taking it would take whatever else the screen put in it.
        walk(obj.list, obj);
        return;
      }
      if (claimed.has(obj)) return;
      const measured = partBox(obj);
      if (measured === null || !isPartOf(measured, box)) return;
      found.push({
        obj: obj as Part["obj"],
        parent,
        box: measured,
        // Inside a container Phaser renders in LIST order and ignores depth;
        // at the top level the display list is depth-sorted. One key that is
        // right either way, so the parts go back down in the order they were
        // already drawn in.
        order: parent === null ? (obj as Part["obj"]).depth * 1e6 + i : i,
      });
    });
  };
  walk(scene.children.list, null);
  return found;
}

/**
 * Lift a control's parts into one container anchored on its centre.
 *
 * Returns null when there is nothing to lift, which is a real answer and not a
 * failure: a target may opt out (`pop: false`), and a control drawn with
 * something this kit cannot measure has to stay at one size rather than grow in
 * pieces.
 */
function wrapTarget(
  scene: Phaser.Scene,
  target: FocusTarget,
  claimed: Set<unknown>,
): Pop | null {
  if (target.pop === false) return null;
  if (target.w <= 0 || target.h <= 0) return null;
  const all = partsAt(scene, target, claimed);
  if (all.length === 0) return null;

  // ONE PARENT PER CONTROL. The plate is the biggest part, so its parent is the
  // container the control lives in; a stray part from somewhere else in the
  // scene graph is left where it is rather than dragged across parents, which
  // would change what it draws over.
  const biggest = all.reduce((a, b) => (a.box.w * a.box.h >= b.box.w * b.box.h ? a : b));
  const parent = biggest.parent;
  const parts = all.filter((p) => p.parent === parent).sort((a, b) => a.order - b.order);

  // The centre, in the coordinate space the parts are positioned in.
  let cx = target.x + target.w / 2;
  let cy = target.y + target.h / 2;
  if (parent !== null) {
    const local = parent.getWorldTransformMatrix().applyInverse(cx, cy, new Phaser.Math.Vector2());
    cx = local.x;
    cy = local.y;
  }

  const container = scene.add.container(cx, cy).setName(`${POP_NAME_PREFIX}${target.id}`);
  const home = parts.map((part) => ({ obj: part.obj, parent: part.parent, x: part.obj.x, y: part.obj.y }));
  if (parent === null) {
    container.setDepth(Math.max(...parts.map((p) => p.obj.depth)));
  } else {
    parent.add(container);
  }
  for (const part of parts) {
    claimed.add(part.obj);
    container.add(part.obj);
    part.obj.x -= cx;
    part.obj.y -= cy;
  }

  // A LOCKED CONTROL NEVER GROWS (D73), the same rule `ui/controls.ts` holds.
  // Growth is the loudest promise this kit makes and a locked stop does not
  // answer Enter.
  const scale = target.locked === true ? 1 : focusPopScale(target.w);
  const pop: Pop = {
    id: target.id,
    container,
    scale,
    popped: false,
    tween: null,
    setPopped(next: boolean) {
      if (pop.popped === next) return;
      pop.popped = next;
      const to = next ? scale : 1;
      // Both directions replace whatever was running. A pointer swept across
      // four rows fires this eight times; without the handle the old tweens
      // keep animating and fight the new one, which reads as a control that
      // judders instead of settling.
      pop.tween?.remove();
      pop.tween = scene.tweens.add({
        targets: container,
        scaleX: to,
        scaleY: to,
        duration: DUR.focus,
        ease: EASE.pop,
      });
    },
    unwrap() {
      pop.tween?.remove();
      pop.tween = null;
      for (const slot of home) {
        claimed.delete(slot.obj);
        // A part destroyed by the scene has already left the container; asking
        // for it back would resurrect nothing and throw on the way.
        if (slot.obj.parentContainer !== container) continue;
        slot.obj.x = slot.x;
        slot.obj.y = slot.y;
        if (slot.parent === null) scene.children.add(slot.obj);
        else slot.parent.add(slot.obj);
      }
      container.destroy();
    },
  };
  return pop;
}

export type MenuAxis = "horizontal" | "vertical";

export interface KeyboardMenuOptions {
  readonly axis?: MenuAxis;
  /**
   * Escape / Backspace. AC-18.1: every screen is returnable by keyboard.
   *
   * REQUIRED, AND THAT IS THE FIX (UR-86). It was optional, and six of the
   * seven screens on this kit simply never passed one - including the MAP,
   * which is the hub: every route out of it goes deeper, so Escape doing
   * nothing left a child with no way back to the title at all. An optional
   * back is an opt-in promise, and AC-18.1 is not optional.
   *
   * A screen that must NOT be escapable still has to say so: pass a no-op with
   * the reason beside it. Warp is mid-jump; Results and Beacon would let a
   * child rewind story state that has already been written. Those are
   * decisions, and now they are written down instead of missing.
   */
  readonly onBack: () => void;
  readonly wrap?: boolean;
  readonly startIndex?: number;
}

export interface KeyboardMenu {
  readonly index: number;
  readonly targets: readonly FocusTarget[];
  focus(index: number): void;
  /**
   * Replace the targets. Focus goes to the PRIMARY target unless `focusId`
   * names one - which is how a screen says "this rebuild is different", e.g.
   * results putting the caret on its one-time opt-in question while that
   * question is on screen.
   */
  setTargets(targets: readonly FocusTarget[], focusId?: string): void;
  destroy(): void;
}

/**
 * Where the caret goes when a screen opens: an explicit `startIndex` if the
 * screen computed one (the map focuses the stop you are on), otherwise the
 * PRIMARY target, otherwise the first.
 */
function openingIndex(
  list: readonly FocusTarget[],
  startIndex: number | undefined,
): number {
  const last = Math.max(0, list.length - 1);
  if (startIndex !== undefined) return Math.min(Math.max(startIndex, 0), last);
  const primary = list.findIndex((t) => t.primary === true);
  return primary >= 0 ? primary : 0;
}

/**
 * List navigation (D37, AC-18.1). Arrows on the menu's axis move, Tab and
 * Shift+Tab always move, Enter and Space activate, Escape goes back - and
 * every target is also a hit area, so the mouse reaches exactly the same set of
 * things the keyboard does and nothing more.
 *
 * Tab is handled explicitly and its default prevented: the game is a canvas,
 * so the browser's own focus order would walk out of the document and strand
 * the player, which is the exact failure AC-18.1 exists to catch.
 *
 * POINTER RULES, the same three the UI kit uses (ui/focus.ts):
 *   hover  -> focus. One highlight in this UI, and it is the ring.
 *   press  -> focus, then activate. A locked target only focuses.
 *   the keyboard path is untouched and remains sufficient on its own.
 */
export function createKeyboardMenu(
  scene: Phaser.Scene,
  ring: FocusRing,
  targets: readonly FocusTarget[],
  options: KeyboardMenuOptions,
): KeyboardMenu {
  const axis = options.axis ?? "vertical";
  const wrap = options.wrap ?? true;
  let list = [...targets];
  let index = openingIndex(list, options.startIndex);
  let zones: Phaser.GameObjects.Zone[] = [];
  /**
   * One slot per target, in list order, holding the container that breathes -
   * or null where there was nothing to lift (`wrapTarget`). Parallel to `list`
   * on purpose: `focus` has an index, not an id, and a Map keyed by id would
   * quietly do the wrong thing on the one screen that repeats an id across a
   * rebuild.
   */
  let pops: (Pop | null)[] = [];
  /** Objects already lifted, so two overlapping targets cannot claim one plate. */
  const claimed = new Set<unknown>();

  const step = (delta: number): void => {
    if (list.length === 0) return;
    let next = index + delta;
    if (wrap) next = (next + list.length) % list.length;
    else next = Math.min(Math.max(next, 0), list.length - 1);
    focus(next);
    // D62 "UI sounds for every interaction" / AC-21.3 `uiNav`. The hook is the
    // menu kit's (ui/focus.ts) so both keyboard menus in this game make the
    // same sound; boot installs it once. `focus()` itself stays silent: it is
    // also how a screen restores the caret after a restart, and a blip there
    // would make a settings row chirp at itself.
    uiSoundBlip("nav");
  };

  function focus(i: number): void {
    if (list.length === 0) return;
    index = Math.min(Math.max(i, 0), list.length - 1);
    const target = list[index];
    if (target !== undefined) ring.moveTo(target);
    // RULE 5 OF THE FOCUS MODEL (`ui/controls.ts`): size is a STATE. Exactly
    // one control is grown, by construction - every slot is told, and only one
    // is told true - so the pointer leaving a control does nothing to it and
    // only another control taking focus brings it back down.
    pops.forEach((pop, i2) => pop?.setPopped(i2 === index));
    scene.events.emit("kb-focus", index, target);
  }

  /**
   * One invisible hit area per target, rebuilt whenever the targets are.
   *
   * Built from the SAME rectangle the focus ring is drawn around, so what the
   * ring says is clickable and what is clickable are one rectangle rather than
   * two that can drift apart.
   */
  /**
   * Lift every target's drawing into its own container, from scratch.
   *
   * Rebuilt rather than reconciled whenever the targets are, because a screen
   * that calls `setTargets` has usually REDRAWN itself (results, when the
   * opt-in question is answered) and the old containers are holding objects
   * that no longer exist.
   */
  function buildPops(): void {
    for (const pop of pops) pop?.unwrap();
    pops = list.map((target) => wrapTarget(scene, target, claimed));
  }

  /**
   * ONE RECTANGLE, ONE HIT ZONE (UR-111).
   *
   * The Briefing drew TWO ways out of itself on the same 224x48 rectangle: a
   * `kb-hit:briefing-back` zone owned by `drawBackChip`, and a `kb-hit:back`
   * zone the menu builds for the `back` target the scene also declares. Both
   * called `goBack`, so nothing was broken to a player - but the pointer e2e's
   * whole claim is that a screen's hit areas ARE its focusable set, and a
   * screen with a spare hit area is a screen where that claim has stopped being
   * checkable. It also meant two hand cursors stacked on one chip.
   *
   * The menu's zone is the one that survives, because it is the one wired to
   * focus: `drawBackChip`'s zone only ever answered a click. A chip on a screen
   * with no menu (Pre-flight) is not touched - it is that screen's only pointer
   * route out, and removing it would take the way out with it.
   */
  function dropDuplicateZone(target: FocusTarget): void {
    for (const obj of [...scene.children.list]) {
      if (!(obj instanceof Phaser.GameObjects.Zone)) continue;
      if (!obj.name.startsWith(HIT_ZONE_PREFIX)) continue;
      if (obj.name === `${HIT_ZONE_PREFIX}${target.id}`) continue;
      if (
        Math.abs(obj.x - target.x) > 0.5 ||
        Math.abs(obj.y - target.y) > 0.5 ||
        Math.abs(obj.width - target.w) > 0.5 ||
        Math.abs(obj.height - target.h) > 0.5
      ) {
        continue;
      }
      obj.destroy();
    }
  }

  function bindPointers(): void {
    for (const zone of zones) zone.destroy();
    zones = [];
    for (const [i, target] of list.entries()) {
      if (target.w <= 0 || target.h <= 0) continue;
      dropDuplicateZone(target);
      const zone = scene.add
        .zone(target.x, target.y, target.w, target.h)
        .setOrigin(0, 0)
        // Named so the pointer e2e can enumerate a screen's hit areas and check
        // they are exactly the focusable set (see ui/controls.ts for the same).
        .setName(`${HIT_ZONE_PREFIX}${target.id}`)
        .setDepth(ring.graphics.depth + 1)
        .setInteractive({ useHandCursor: target.locked !== true });
      zone.on("pointerover", () => {
        if (i === index) return;
        focus(i);
        uiSoundBlip("nav");
      });
      zone.on("pointerdown", () => {
        focus(i);
        if (target.locked === true) return;
        target.activate?.();
        uiSoundBlip("activate");
      });
      zones.push(zone);
    }
  }

  const forward = axis === "horizontal" ? ["ArrowRight", "ArrowDown"] : ["ArrowDown", "ArrowRight"];
  const backward = axis === "horizontal" ? ["ArrowLeft", "ArrowUp"] : ["ArrowUp", "ArrowLeft"];

  const onKey = (event: KeyboardEvent): void => {
    if (event.key === "Tab") {
      event.preventDefault();
      step(event.shiftKey ? -1 : 1);
      return;
    }
    if (forward.includes(event.key)) {
      event.preventDefault();
      step(1);
      return;
    }
    if (backward.includes(event.key)) {
      event.preventDefault();
      step(-1);
      return;
    }
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      list[index]?.activate?.();
      uiSoundBlip("activate");
      return;
    }
    if (event.key === "Escape" || event.key === "Backspace") {
      event.preventDefault();
      options.onBack?.();
    }
  };

  scene.input.keyboard?.on("keydown", onKey);
  bindPointers();
  buildPops();
  focus(index);

  return {
    get index() {
      return index;
    },
    get targets() {
      return list;
    },
    focus,
    /**
     * Replace the targets. The caret goes to the PRIMARY target, not to
     * whatever index happened to be current: a screen that rebuilds its buttons
     * (results, once the relative-board prompt is answered) is opening a new
     * set of choices, and the forward one is the default for the new set the
     * same way it was for the first.
     *
     * `focusId` overrides that for the case where the screen is ASKING
     * something. A one-time question the caret skips past is a question nobody
     * answers, and "the forward action is the default" is a rule about
     * replay-versus-continue, not a licence to focus past a prompt.
     */
    setTargets(next: readonly FocusTarget[], focusId?: string) {
      list = [...next];
      bindPointers();
      buildPops();
      const named = focusId === undefined ? -1 : list.findIndex((t) => t.id === focusId);
      focus(named >= 0 ? named : openingIndex(list, undefined));
    },
    destroy() {
      scene.input.keyboard?.off("keydown", onKey);
      for (const zone of zones) zone.destroy();
      zones = [];
      // The parts go back where the scene left them before the containers go,
      // so a screen that outlives its menu - or a test that measures the scene
      // graph afterwards - sees what it drew rather than an empty display list.
      for (const pop of pops) pop?.unwrap();
      pops = [];
    },
  };
}

/**
 * What a scene exposes to the e2e suite. A canvas has no DOM to assert
 * against, so every screen publishes a plain-object view of the state its ACs
 * talk about. It is read-only and derived; nothing in the game reads it back.
 */
export interface SceneSnapshot {
  readonly scene: string;
  readonly [key: string]: unknown;
}

export interface Snapshotable {
  snapshot(): SceneSnapshot;
}

export function hasSnapshot(scene: Phaser.Scene): scene is Phaser.Scene & Snapshotable {
  return typeof (scene as Partial<Snapshotable>).snapshot === "function";
}

/**
 * Every string currently rendered by the scene, containers included.
 *
 * This exists for AC-11.3 and AC-22b.1, which are both claims about what is
 * ABSENT from a screen. An assertion that a score is not shown is only worth
 * something if the test can see everything that IS shown, so the snapshot
 * carries the full text of the screen and the e2e scans it.
 */
export function visibleText(scene: Phaser.Scene): string[] {
  const out: string[] = [];
  const walk = (objects: Phaser.GameObjects.GameObject[]): void => {
    for (const obj of objects) {
      if (obj instanceof Phaser.GameObjects.Container) {
        walk(obj.list);
        continue;
      }
      if (obj instanceof Phaser.GameObjects.Text) {
        if (obj.visible && obj.alpha > 0.02) out.push(obj.text);
      }
    }
  };
  walk(scene.children.list);
  return out;
}

/**
 * THE WAY OUT, AS ONE ELEMENT (UR-98).
 *
 * ================== WHAT WAS REPORTED ==================
 * The Briefing and Pre-flight both show a chip reading "back to the map", and
 * they were two different controls wearing one name. Measured on the served
 * build:
 *
 *   briefing   224 x 48   INK.panel        TYPE.caption   INK.textDim
 *   preflight  262 x 66   INK.panelRaised  TYPE.label     INK.text
 *
 * Different size, plate, type and ink, on two screens a child walks straight
 * between. Neither was wrong alone; having two was.
 *
 * ================== WHY A COMPONENT AND NOT A CONSTANT ==================
 * Sharing only the RECTANGLE is what they already did - both call
 * `grid.backCorner` - and it did not stop them diverging, because the plate,
 * the type and the ink stayed each screen's own. So the drawing lives here too:
 * a scene asks for the chip and gets the chip.
 *
 * The size is the Briefing's 224 x 48 rather than Pre-flight's 262 x 66,
 * deliberately the smaller: this is the quiet way out on a screen whose forward
 * action is the point, which is UR-60's rule.
 */
export const BACK_CHIP_SIZE = { w: 224, h: 48 } as const;

/** Where it sits. `grid.backCorner`, so both screens share the foot line. */
export const backChipRect = (): Rect => backCorner(BACK_CHIP_SIZE.w, BACK_CHIP_SIZE.h);

export interface BackChipOptions {
  readonly depth: number;
  readonly label: string;
  readonly lang: Lang;
  readonly onPress: () => void;
  /** `HIT_ZONE_PREFIX` + this. The pointer e2e enumerates these names. */
  readonly hitId: string;
  /**
   * THE POINTER REACHING THE CHIP MAKES IT THE FOCUSED CONTROL (UR-111).
   *
   * This chip was the only control in the game bound to `pointerdown` and
   * nothing else. `ui/focus.ts` states the invariant it broke in its own words:
   * "to be clickable you must be in the focus list" - hovering every other
   * control in this game moves focus to it, and hovering this one did nothing
   * at all, so the way out of two screens was the one thing a child could click
   * without the screen ever admitting it was there.
   *
   * It is a callback rather than a `FocusList` because the chip does not own
   * the screen's focus - the screen does. A scene with a menu passes
   * `menu.focus` bound to this chip's index (`backChipTarget` below builds the
   * matching target); a scene without one passes nothing, and gets exactly the
   * behaviour it had. That second case is Pre-flight, and it is a gap in the
   * screen rather than in the chip: Pre-flight has no focus list and no focus
   * ring, so there is nothing for a hover to move.
   */
  readonly onFocus?: () => void;
}

/**
 * The chip as a `FocusTarget`, so a screen wires it into its menu in one line
 * instead of restating `backChipRect()` beside the call that drew it.
 *
 * The Briefing restates it today, which is how it came to own two hit areas on
 * one rectangle (`dropDuplicateZone`). A screen that asks for the target here
 * cannot drift from the drawing, because both read `backChipRect`.
 */
export function backChipTarget(id: string, onPress: () => void): FocusTarget {
  const rect = backChipRect();
  return { id, x: rect.x, y: rect.y, w: rect.w, h: rect.h, activate: onPress };
}

/**
 * Draw it. Plate, label and the pointer route, in that z-order.
 *
 * The KEYBOARD route out is not here: Escape belongs to the scene's own
 * `onBack`, and a chip that installed a key handler would be a second owner of
 * it (UR-86 made `onBack` required for exactly that reason).
 */
export function drawBackChip(
  scene: Phaser.Scene,
  options: BackChipOptions,
): Phaser.GameObjects.GameObject[] {
  const rect = backChipRect();
  const face = plate(scene, rect.x, rect.y, rect.w, rect.h, {
    fill: INK.panel,
  }).setDepth(options.depth);
  const text = label(scene, rect.x + rect.w / 2, rect.y + rect.h / 2, options.label, {
    size: TYPE.caption,
    color: INK.textDim,
    align: "center",
    lang: options.lang,
  })
    .setOrigin(0.5)
    .setDepth(options.depth + 1);
  const zone = scene.add
    .zone(rect.x, rect.y, rect.w, rect.h)
    .setOrigin(0, 0)
    .setName(`${HIT_ZONE_PREFIX}${options.hitId}`)
    .setDepth(options.depth + 2)
    .setInteractive({ useHandCursor: true })
    // Hover focuses, press focuses then activates - the same two rules every
    // other control in this game follows (`ui/focus.ts`, `ui/controls.ts`).
    .on("pointerover", () => options.onFocus?.())
    .on("pointerdown", () => {
      options.onFocus?.();
      options.onPress();
    });
  return [face, text, zone];
}
